const playerRankingData=window.UHC_PLAYER_RANKINGS;
const rankingPlayerAnchor=name=>'rank-player-'+encodeURIComponent(name);
const rankingTier=(value,tip)=>`<span class="pr-tier pr-tier-${value}" ${chartTip(tip)}> ${value} </span>`;
const rankingRate=value=>(value*100).toFixed(1)+'%';
const playerScoreTip=p=>`${p.name} · ${p.score.toFixed(2)} / 100\nCombat: ${p.components.combat.points.toFixed(2)} / 40\nVictories: ${p.components.victories.points.toFixed(2)} / 30\nDefense: ${p.components.defense.points.toFixed(2)} / 20\nSurvival: ${p.components.survival.points.toFixed(2)} / 10\nTeam Kill deduction: −${p.penalty.toFixed(2)}\n${p.games} games · Five-game sample adjustment`;
const prStat=(p,key,primary,secondary)=>{const c=p.components[key];return `<div class="pr-stat" ${chartTip(`${key==='combat'?'Combat':key==='victories'?'Victories':key==='ironman'?'Ironman':'Survival'} · Tier ${c.tier}\n${primary} · ${secondary}\nAdjusted rate: ${key==='combat'?c.adjustedRate.toFixed(3)+' kills / game':rankingRate(c.adjustedRate)}\nFull-points benchmark: ${key==='combat'?c.benchmark+' kills / game':rankingRate(c.benchmark)}\nScore contribution: ${c.points.toFixed(2)} / ${c.weight}`)}><span class="pr-value-line"><span class="pr-stat-value">${primary}</span><span class="pr-mini-tier pr-tier-${c.tier}">${c.tier}</span></span><span class="pr-stat-sub">${secondary}</span></div>`};
function prDefense(p){
 const c=p.components.defense;
 return `<div class="pr-stat pr-defense" ${chartTip(`Defense · Tier ${c.tier}\nAverage share of other timed deaths outlasted: ${p.outlastRate==null?'N/A':rankingRate(p.outlastRate)}\nCoverage: ${p.durabilityGames} / ${p.games} games\n${p.ironmen} Ironmen · ${rankingRate(p.ironRate)} of games\nIronman contribution: ${c.ironPoints.toFixed(2)} / 10\nDurability contribution: ${c.durabilityPoints.toFixed(2)} / 10\nTotal Defense: ${c.points.toFixed(2)} / 20\nOwn deaths excluded; tied times are not outlasted.`)}><span class="pr-value-line"><span class="pr-stat-value">${p.outlastRate==null?'N/A':rankingRate(p.outlastRate)}</span><span class="pr-mini-tier pr-tier-${c.tier}">${c.tier}</span></span><span class="pr-stat-sub">outlasted · ${p.ironmen} Ironmen</span></div>`;
}
function playerRankPodium(){
 return playerRankingData.players.slice(0,3).map((p,i)=>`<a class="pr-podium-card pr-podium-${i+1}" href="#${rankingPlayerAnchor(p.name)}"><div class="pr-podium-top"><span class="pr-podium-place">0${p.rank}</span><span class="pr-podium-tag">${i===0?'THE FRONT RUNNER':i===1?'THE CHALLENGER':'THE CONTENDER'}</span><span class="pr-podium-arrow" aria-hidden="true">↘</span></div><div class="pr-podium-person">${playerFace(p.name)}<div><h3>${escape(p.name)}</h3><p>${p.games} games · S${p.firstSeason}–S${p.lastSeason}</p></div></div><div class="pr-podium-score"><strong>${p.score.toFixed(2)}<small>/ 100</small></strong><span class="pr-tier pr-tier-${p.tier}">${p.tier}</span></div><div class="pr-score-track"><i style="width:${p.score}%"></i></div><div class="pr-podium-stats"><span><b>${p.kills}</b>PVP KILLS</span><span><b>${p.wins}</b>VICTORIES</span><span><b>${p.ironmen}</b>IRONMEN</span></div></a>`).join('');
}
function playerRankingRow(p){
 const componentLabels={combat:'Combat',victories:'Victories',defense:'Defense',survival:'Survival'};
 return `<details class="pr-row" id="${rankingPlayerAnchor(p.name)}"><summary class="pr-row-summary"><span class="pr-position">${String(p.rank).padStart(2,'0')}</span><span class="pr-identity">${playerFace(p.name)}<span><b>${escape(p.name)}</b><small>${p.games} games · best game: ${p.bestKills} kills</small></span></span>${prStat(p,'combat',p.killsPerGame.toFixed(2),`${p.kills} PVP kills`)}${prStat(p,'victories',rankingRate(p.winRate),`${p.wins} team wins`)}${prDefense(p)}<div class="pr-discipline" ${chartTip(`Discipline · Tier ${p.disciplineTier}\n${p.teamKills} Team Kills over ${p.games} games\n${p.teamKillRate.toFixed(3)} per game\nDeduction: −${p.penalty.toFixed(2)} points\nZero Team Kills earns S discipline, without adding free score points.`)}><span class="pr-value-line"><span class="pr-stat-value">${p.teamKills}</span><span class="pr-mini-tier pr-tier-${p.disciplineTier}">${p.disciplineTier}</span></span><span class="pr-stat-sub">Team Kills</span></div><span class="pr-final-score" ${chartTip(playerScoreTip(p))}><strong>${p.score.toFixed(2)}</strong>${rankingTier(p.tier,`Overall tier ${p.tier}\n${playerScoreTip(p)}`)}</span><span class="pr-row-expand" aria-hidden="true">+</span></summary><div class="pr-row-detail"><div class="pr-detail-heading"><div><p class="eyebrow">INSIDE THE SCORE</p><h3>${escape(p.name)}’s performance breakdown</h3></div><a class="pr-profile-link" href="${profileHref(p.name)}">Open player profile ↗</a></div><div class="pr-breakdown-grid">${Object.entries(p.components).map(([key,c])=>`<div class="pr-breakdown-stat"><div><span>${componentLabels[key]}</span><b>${c.points.toFixed(2)} <small>/ ${c.weight}</small></b></div><div class="pr-component-track"><i style="width:${100*c.points/c.weight}%"></i></div><p>${key==='defense'?`Ironman ${c.ironPoints.toFixed(2)} / 10 · Outlast ${c.durabilityPoints.toFixed(2)} / 10`:key==='survival'?`${p.survived} / ${p.games} games survived · ${rankingRate(p.survivalRate)}`:`Tier ${c.tier} · ${Math.round(100*c.points/c.weight)}% of benchmark`}</p></div>`).join('')}</div><details class="pr-durability-history"><summary>Durability by season · ${p.durabilityGames} / ${p.games} games with usable death timing</summary><p>Average share of other timed deaths outlasted: ${p.outlastRate==null?'N/A':rankingRate(p.outlastRate)}. Across those games: ${p.outlastedDeaths} earlier deaths out of ${p.otherTimedDeaths} other timed deaths. Each game has equal weight in the average.</p><div>${p.history.map(h=>`<a href="#season-${h.season}"><b>S${h.season}</b><span>${h.deathOutlastRate==null?'N/A':rankingRate(h.deathOutlastRate)}</span></a>`).join('')}</div></details><div class="pr-detail-bottom"><span class="${p.penalty?'pr-penalty':'pr-clean'}">${p.penalty?`Team Kill deduction · −${p.penalty.toFixed(2)} points`:'Clean discipline · No recorded Team Kills'}</span><span>Five prior games at the overall average soften small samples.</span></div><div class="pr-form"><span>RECENT FIVE GAMES</span>${p.history.slice(-5).map(h=>`<a href="#season-${h.season}" ${chartTip(`Season ${h.season}\n${h.team}\n${h.kills} PVP kills${h.win?' · Team victory':''}${h.iron?' · Ironman':''}${h.teamKills?' · '+h.teamKills+' Team Kills':''}`)}><b>S${h.season}</b><span>${h.kills} K</span>${h.win?'<i>W</i>':''}${h.iron?'<i>◈</i>':''}</a>`).join('')}</div></div></details>`;
}
function playerRankingRows(){
 const q=$('pr-search').value.trim().toLowerCase(),filter=$('pr-tier-filter').value,order=$('pr-order').value;
 return playerRankingData.players.filter(p=>(!filter||filter==='all'||p.tier===filter)&&(!q||[p.name,...p.aliases].some(n=>n.toLowerCase().includes(q)))).sort((a,b)=>order==='kills'?b.killsPerGame-a.killsPerGame||a.rank-b.rank:order==='wins'?b.winRate-a.winRate||a.rank-b.rank:order==='defense'?b.components.defense.points-a.components.defense.points||a.rank-b.rank:order==='discipline'?a.teamKillRate-b.teamKillRate||a.rank-b.rank:order==='games'?b.games-a.games||a.rank-b.rank:a.rank-b.rank);
}
function renderPlayerRankings(){
 const players=playerRankingRows();$('pr-result-count').textContent=`${players.length} of ${playerRankingData.players.length} eligible players`;
 $('pr-leaderboard').innerHTML=players.map(playerRankingRow).join('')||'<div class="empty">No players match this name and tier.</div>';
}
function switchRankingsMode(mode){
 $('team-rankings-panel').hidden=mode!=='teams';$('player-rankings-panel').hidden=mode!=='players';
 document.querySelectorAll('[data-ranking-mode]').forEach(button=>{const active=button.dataset.rankingMode===mode;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});
 if(mode==='players')renderPlayerRankings();
}
function initializePlayerRankings(){
 $('pr-podium').innerHTML=playerRankPodium();
 $('pr-summary').textContent=`${playerRankingData.players.length} ranked players · Minimum five games · Current workbook`;
 $('pr-method-text').textContent=playerRankingData.method;$('pr-tier-method').textContent=playerRankingData.tiers;$('pr-method-notes').textContent=playerRankingData.notes;
 $('pr-search').addEventListener('input',renderPlayerRankings);$('pr-tier-filter').addEventListener('change',renderPlayerRankings);$('pr-order').addEventListener('change',renderPlayerRankings);
 $('pr-reset').addEventListener('click',()=>{$('pr-search').value='';$('pr-tier-filter').value='all';$('pr-order').value='rank';renderPlayerRankings();});
 document.addEventListener('click',event=>{const button=event.target.closest('[data-ranking-mode]');if(button){const hash=button.dataset.rankingMode==='players'?'#rankings-players':'#rankings';if(location.hash===hash)switchRankingsMode(button.dataset.rankingMode);else location.hash=hash;}});
}
